from abc import ABCMeta, abstractmethod
import attr
import six
from typing import List, Optional, Union  # noqa: F401
from .connection_details import SshServiceDetails  # noqa: F401


@six.add_metaclass(ABCMeta)
class ChannelEmulator(object):

    @abstractmethod
    def __init__(self, channel_emulator_port_numbers, model=None, version=None):
        # type: (List[int], Optional[str], Optional[str]) -> None
        """
        :param List[Union[str, int]] channel_emulator_port_numbers: List of Port numbers on the channel emulator
        :param Optional[str] model: model of the channel emulator
        :param Optional[str] version: version of the channel emulator
        """
        self.channel_emulator_ports = {i: ChannelEmulatorPort(self, i) for i in channel_emulator_port_numbers}
        self.model = model
        self.version = version


@attr.s(cmp=False)
class ChannelEmulatorPort(object):
    """
    input or output port on channel emulaotr
    :param ChannelEmulator channel_emulator: object of subclass of ChannelEmulator
    :param Union[str, int] port_no: Port/Outlet number on the channel_emulator
    """
    channel_emulator = attr.ib(type=ChannelEmulator)
    port_no = attr.ib(type=Union[str, int])


class Vertex(ChannelEmulator):
    def __init__(self, ip_addr, channel_emulator_port_numbers, port=None, proxy=None, model=None, version=None):
        # type: (str, List[int], Optional[int], Optional[SshServiceDetails], Optional[str], Optional[str]) -> None
        """
        A channel emulator from SPIRENT

        :param Optional[str] ip_addr: IP ADDRESS
        :param List[Union[str, int]] channel_emulator_port_numbers: List of Port numbers on the channel emulator
        :param Optional[int] port: vertex's port for management
        :param Optional[SshServiceDetails] proxy: ssh proxy
        :param Optional[str] model: model of the channel emulator
        :param Optional[str] version: version of the channel emulator
        """
        super(Vertex, self).__init__(channel_emulator_port_numbers=channel_emulator_port_numbers,
                                     model=model,
                                     version=version)
        self.vendor = "SPIRENT"
        self.ip_addr = ip_addr
        self.port = port or 3000
        self.proxy = proxy

    def __taf_contract_ssh__(self):
        if self.proxy is None:
            raise ValueError(
                f"SSH proxy information is not set in this configuration object "
                f"({self.__class__!r})"
            )
        return self.proxy.__taf_contract_ssh__()
